export const RESPECTING_DIFFERENCES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Perbedaan pendapat itu wajar",q:"Ketika anggota tim punya pendapat berbeda tentang cara mengerjakan proyek, itu...",options:["Hal wajar & normal — orang punya pengalaman & cara berpikir berbeda","Tanda tim yang buruk, karena tim baik harus sepakat dalam semua hal","Berarti ada anggota yang salah paham dan perlu dikoreksi"],answer:0,explain:"Tim tanpa perbedaan pendapat sering hanya mengikuti satu suara. Perbedaan bisa menghasilkan keputusan lebih baik.",hint:"Wajar & normal, atau tanda buruk?"},
{n:2,type:"mcq",micro:"Kritik ide, bukan orang",q:"Cara menyampaikan ketidaksetujuan yang menjaga hubungan:",options:["Diam saja lalu memusuhi orang itu diam-diam setelah rapat selesai","'Aku kurang setuju dengan ide itu karena...' — fokus pada idenya","'Kamu memang punya ide aneh terus' — menyerang pribadi orangnya"],answer:1,explain:"Kamu bisa menolak ide dengan tegas tanpa menyerang atau merendahkan orang yang mengusulkannya.",hint:"Kritik idenya, atau serang orangnya?"},
{n:3,type:"mcq",micro:"Mendengar sebelum membantah",q:"Sebelum menyampaikan ketidaksetujuanmu, sebaiknya...",options:["Potong di tengah pembicaraan agar pendapatmu cepat tersampaikan","Menganggap sudah tahu apa yang akan dikatakannya, jadi tak perlu menunggu ia selesai","Dengarkan pendapat orang sampai selesai & pastikan kamu paham maksudnya"],answer:2,explain:"Membantah pendapat yang belum kamu pahami sepenuhnya sering meleset & terasa tidak menghormati.",hint:"Dengar & pahami dulu, atau potong?"},
{n:4,type:"mcq",micro:"Perbedaan bisa memperkuat",q:"Dua anggota punya ide berbeda untuk poster: satu ingin fokus gambar, satu fokus data. Hasil terbaik mungkin...",options:["Menggabungkan yang terbaik dari keduanya: gambar kuat + data ringkas yang jelas","Memilih satu ide saja dan membuang yang lain, supaya poster terlihat konsisten","Bertengkar sampai salah satu menyerah, karena ide yang bertahan paling lama paling kuat"],answer:0,explain:"Perbedaan pendapat sering bukan 'A atau B' tapi kesempatan menemukan 'A + B' yang lebih baik.",hint:"Gabungkan yang terbaik, atau buang satu / bertengkar?"},
{n:5,type:"mcq",micro:"Menghormati saat kalah suara",q:"Idemu kalah suara dalam keputusan tim. Sikap yang menghormati tim:",options:["Terus mengungkit bahwa idemu lebih baik tiap ada kesempatan, sampai tim meninjau ulang","Sampaikan kekecewaan bila perlu, lalu dukung keputusan tim & beri yang terbaik","Menyabotase keputusan diam-diam karena kesal, supaya terbukti idemu yang benar"],answer:1,explain:"Menerima kekalahan suara dengan lapang & tetap berkontribusi penuh adalah tanda kematangan.",hint:"Dukung keputusan tim, atau sabotase / ungkit?"},
{n:6,type:"mcq",micro:"Bertanya alasan",q:"Temanmu punya pendapat yang menurutmu aneh. Respons yang menghormati:",options:["'Idemu nggak masuk akal, jadi jangan dibahas lagi di sini.'","Memutar mata sambil menghela napas lalu mengabaikan ucapannya","'Aku penasaran, apa yang bikin kamu berpikir begitu?'"],answer:2,explain:"Bertanya alasan menunjukkan kamu menganggap pendapatnya layak dipertimbangkan, & sering mengungkap hal yang kamu lewatkan.",hint:"Tanya alasannya, atau meremehkan?"},
{n:7,type:"mcq",micro:"Perbedaan gaya kerja",q:"Anggota timmu suka mengerjakan tugas jauh sebelum tenggat; kamu suka mendekati tenggat. Sikap:",options:["Hormati perbedaan, tapi sepakati tenggat internal bersama yang bisa dipenuhi semua","Paksa anggota bekerja dengan gayamu, karena gaya yang cocok untukmu cocok bagi semuanya","Kritik gaya kerja anggota lain sebagai cara yang salah dan malas, supaya ia mau berubah"],answer:0,explain:"Perbedaan gaya bukan soal benar-salah. Yang penting: kesepakatan bersama soal kapan bagian harus jadi.",hint:"Hormati + sepakati tenggat bersama, atau paksa satu gaya?"},
{n:8,type:"mcq",micro:"Menyampaikan pendapat tanpa memaksa",q:"Cara menyampaikan pendapatmu di tim yang tetap terbuka:",options:["'Terserah kalian aja, aku ikut.' (padahal kamu punya pendapat kuat dan penting soal ini)","'Menurutku sebaiknya begini, karena... Tapi aku terbuka kalau ada yang lihat berbeda.'","'Pokoknya harus begini. Titik. Tidak perlu dibahas lagi, aku yakin ini yang paling benar.'"],answer:1,explain:"Menyampaikan pendapat dengan alasan + membuka ruang diskusi lebih efektif daripada memaksa atau menahan.",hint:"Pendapat + alasan + terbuka, atau memaksa / menahan?"},
{n:9,type:"order",micro:"Menanggapi pendapat yang berbeda",q:"Urutkan cara menanggapi anggota yang pendapatnya berbeda darimu.",items:["Dengarkan sampai selesai tanpa memotong","Ulangi inti pendapatnya untuk memastikan kamu paham","Tanyakan alasannya bila belum jelas","Sampaikan pandanganmu dengan alasan, fokus pada idenya"],answer:[0,1,2,3],explain:"Dengar → pahami → tanya alasan → sampaikan pandanganmu (soal ide). Bukan langsung membantah.",hint:"Apa yang dilakukan sebelum menyampaikan pandanganmu?"},
{n:10,type:"mcq",micro:"Nada saat tidak setuju",q:"Nada suara yang menjaga diskusi tetap sehat saat ada perbedaan pendapat:",options:["Meninggi dan mengejek pihak yang dikritik","Sinis dan menyindir di depan teman-teman","Tenang & ramah, meski isinya tegas menolak"],answer:2,explain:"Isi bisa tegas ('aku tidak setuju'), tapi nada yang tenang menjaga orang tidak merasa diserang.",hint:"Tenang & ramah, atau meninggi / sinis?"},
{n:11,type:"tf",micro:"Perbedaan pendapat bisa berguna",q:"Benar atau Salah: Perbedaan pendapat dalam tim, bila dibahas dengan hormat, sering menghasilkan keputusan yang lebih baik daripada bila semua langsung setuju tanpa berpikir.",answer:true,explain:"Perbedaan pendapat memaksa tim menimbang beberapa sisi & menangkap risiko atau ide yang mungkin terlewat.",hint:"Bisa menghasilkan keputusan lebih baik, atau selalu merugikan?"},
{n:12,type:"tf",micro:"Menghormati = harus setuju?",q:"Benar atau Salah: Menghormati pendapat orang lain berarti kamu wajib pada akhirnya menyetujui pendapat mereka.",answer:false,explain:"Sebaliknya, kamu bisa mendengarkan dengan hormat, mempertimbangkan sungguh-sungguh, lalu tetap tidak setuju — selama kamu menyampaikannya dengan cara yang menghargai orangnya.",hint:"Hormat = wajib setuju, atau bisa dengar lalu tetap berbeda?"},
{n:13,type:"mcq",micro:"Perbedaan latar belakang",q:"Anggota timmu dari daerah/keluarga berbeda punya kebiasaan & cara pandang berbeda. Sikap:",options:["Anggap perbedaan itu bisa memperkaya tim; bertanya bila tidak paham, bukan langsung menilai 'aneh' atau 'salah'","Menganggap cara mereka kurang tepat dibanding caramu, sehingga perlu diluruskan agar anggota bekerja sama","Menghindari bekerja dengannya sebisa mungkin, karena kebiasaan yang berbeda mempersulit kerja sama"],answer:0,explain:"Keberagaman sudut pandang menangkap titik buta yang tim seragam lewatkan — asalkan dikelola dengan hormat.",hint:"Memperkaya, atau 'aneh/salah'?"},
{n:14,type:"mcq",micro:"Menahan diri dari langsung menolak",q:"Saat mendengar ide yang tidak kamu suka, kebiasaan baik:",options:["Diam & menolak ide itu dalam hati tanpa bilang apa-apa, lalu mengerjakan bagianmu dengan cara yang kamu sukai sendiri saja","Tahan reaksi awal, cari dulu apa yang mungkin bagus atau masuk akal dari ide itu, baru sampaikan kekhawatiranmu","Langsung berkata 'nggak' sebelum orang itu selesai berbicara, supaya ia tidak membuang waktu menjelaskan sesuatu yang kamu tidak sukai"],answer:1,explain:"Reaksi 'nggak' yang cepat sering emosi. Mencari sisi baik dulu membuat tanggapanmu lebih adil & diskusi lebih produktif.",hint:"Tahan + cari sisi baik dulu, atau langsung 'nggak' / diam menolak?"},
{n:15,type:"mcq",micro:"Perbedaan bukan pertengkaran",q:"Beda 'diskusi yang sehat tentang perbedaan pendapat' & 'pertengkaran':",options:["Keduanya sama saja, karena sama-sama melibatkan perbedaan pendapat yang disampaikan dengan nada tinggi dan sama-sama diakhiri keputusan","Diskusi sehat berarti tidak ada perbedaan pendapat; kalau ada yang berbeda, itu sudah pertengkaran dan harus segera dihentikan oleh ketua","Diskusi sehat: fokus pada ide, semua didengar, tujuannya keputusan lebih baik. Pertengkaran: fokus menyerang & menang, orang merasa terluka"],answer:2,explain:"Perbedaan pendapat tidak harus menjadi pertengkaran. Yang membedakannya adalah fokus (ide vs orang) & tujuan (lebih baik vs menang).",hint:"Fokus ide + keputusan lebih baik, atau menyerang + menang?"},
{n:16,type:"mcq",micro:"Menghargai anggota pendiam yang berbeda",q:"Anggota pendiam menyampaikan pendapat yang berbeda dari mayoritas dengan suara pelan. Sikap tim:",options:["Beri perhatian penuh, minta ia menjelaskan lebih lanjut, & timbang pendapatnya serius — jangan langsung tenggelamkan dengan suara mayoritas","Abaikan saja karena dia sendirian dan suaranya pelan, sebab pendapat mayoritas biasanya lebih tepat daripada pendapat satu orang","Suruh dia ikut pendapat mayoritas saja demi kekompakan tim, karena perbedaan hanya akan memperlambat pengambilan keputusan bersama"],answer:0,explain:"Pendapat minoritas kadang menangkap risiko yang mayoritas lewatkan. Dengarkan sebelum memutuskan.",hint:"Beri perhatian & timbang serius, atau tenggelamkan / suruh ikut?"},
{n:17,type:"mcq",micro:"Mengakui poin lawan",q:"Saat berdiskusi & lawan bicara menyampaikan poin yang benar, sikap yang menghormati:",options:["Langsung ganti topik supaya suasana tidak canggung dan kamu tak perlu mengakui dia benar","Akui: 'Poin kamu soal biaya itu betul, aku belum kepikiran' — lalu lanjutkan diskusi","Pura-pura tidak mendengar poinnya, lalu lanjut membahas pendapatmu sendiri"],answer:1,explain:"Mengakui poin yang benar dari lawan menunjukkan kamu berdiskusi untuk mencari yang terbaik, bukan sekadar menang.",hint:"Akui poin bagusnya, atau abaikan / alihkan?"},
{n:18,type:"mcq",micro:"Perbedaan pendapat soal selera",q:"Tim berdebat soal warna poster (selera). Cara menyelesaikan yang tidak berlarut:",options:["Berdebat berjam-jam mencari 'warna yang benar' menurut tiap orang, sampai akhirnya semua anggota setuju pada satu warna yang sama","Yang paling ngotot dan paling lama bicara yang dimenangkan, karena dianggap paling peduli pada hasil akhir poster tim","Sadari ini soal selera (tidak ada yang 'benar'), lalu voting cepat atau serahkan ke penanggung jawab desain dengan masukan"],answer:2,explain:"Tidak semua perbedaan pendapat perlu diperdebatkan panjang. Soal selera bisa diputuskan cepat.",hint:"Sadari soal selera + voting/serahkan, atau debat panjang / ngotot?"},
{n:19,type:"mcq",micro:"Menjaga hubungan setelah berbeda",q:"Setelah diskusi yang cukup panas soal perbedaan pendapat, sikap yang menjaga tim:",options:["Tegaskan bahwa perbedaan itu soal ide, bukan pribadi: 'Kita beda pendapat soal ini, tapi kita tetap satu tim ya.'","Memusuhi orang yang berbeda pendapat tadi dan tidak lagi mengajaknya bicara dalam kegiatan kelompok","Menyimpan dendam lalu membicarakan orang itu di belakangnya bersama anggota lain di kelompok"],answer:0,explain:"Menegaskan bahwa perbedaan ide tidak mengubah hubungan menjaga tim tetap solid setelah diskusi.",hint:"Tegaskan tetap satu tim, atau memusuhi / dendam?"},
{n:20,type:"open",micro:"Menanggapi perbedaan pendapat",q:"Dalam rapat kelompok, temanmu Rian mengusulkan topik proyek yang menurutmu terlalu sulit & berisiko tidak selesai tepat waktu. Rian terlihat bersemangat. Tulis bagaimana kamu akan menyampaikan ketidaksetujuanmu dengan menghormati Rian, lalu jelaskan pilihanmu.",explain:"Jawaban baik: mengakui sisi baik ide + semangat Rian dulu, menyampaikan ketidaksetujuan dengan alasan spesifik yang fokus pada risiko ide (bukan menyerang Rian), menawarkan alternatif konkret, dan membuka ruang untuk pendapat anggota lain — lalu menjelaskan alasan tiap pilihan.",hint:"Akui sisi baik + semangatnya, sampaikan kekhawatiran dengan alasan spesifik (soal ide), tawarkan alternatif, buka ruang pendapat lain.",sample:"Yang akan kukatakan: 'Rian, aku suka semangatmu soal topik ini, dan idenya memang menarik. Tapi aku agak khawatir soal waktu — topik ini butuh riset yang dalam dan mungkin data yang sulit kita dapat dalam 3 minggu. Menurutmu, gimana kalau kita ambil bagian yang lebih kecil dari topik itu, atau kita cari topik yang mirip tapi lebih terjangkau? Aku pengin dengar juga pendapat yang lain.' Penjelasan pilihanku: (1) Aku mulai dengan mengakui sisi baik idenya dan semangat Rian, supaya ia tidak merasa langsung ditolak mentah-mentah. (2) Aku menyampaikan kekhawatiranku dengan alasan yang spesifik (waktu, kesulitan data), fokus pada risiko idenya, bukan menyebut Rian 'nggak realistis' atau menyerang dia. (3) Aku menawarkan alternatif (memperkecil cakupan atau topik mirip yang lebih terjangkau) supaya diskusi bergerak ke solusi, bukan sekadar menolak. (4) Aku membuka ruang untuk pendapat anggota lain, supaya keputusan diambil bersama dan bukan hanya adu aku vs Rian."},
{n:21,type:"classify",micro:"Menanggapi perbedaan: hormat vs merendahkan",q:"Kelompokkan tiap respons ke 'Menghormati perbedaan' atau 'Merendahkan'.",items:["'Aku lihatnya beda, ini alasanku...'","'Kok bisa mikir gitu sih, aneh banget.'","'Poinmu soal X aku setuju, tapi soal Y aku ragu karena...'","'Terserah, ngapain juga aku dengerin.'"],groups:["Menghormati perbedaan","Merendahkan"],answer:{"Menghormati perbedaan":["'Aku lihatnya beda, ini alasanku...'","'Poinmu soal X aku setuju, tapi soal Y aku ragu karena...'"],"Merendahkan":["'Kok bisa mikir gitu sih, aneh banget.'","'Terserah, ngapain juga aku dengerin.'"]},explain:"Menghormati: menyampaikan pandangan beda dengan alasan, mengakui poin yang benar. Merendahkan: menyebut pendapat 'aneh', menolak mendengar.",hint:"Menyampaikan beda dengan alasan, atau meremehkan / menolak mendengar?"},
{n:22,type:"mcq",micro:"Steelman vs strawman",q:"'Steelman' sebuah pendapat berarti...",options:["Mengabaikan pendapat lawan dan langsung menyampaikan pendapatmu, supaya diskusi lebih cepat","Menyampaikan ulang pendapat lawan dalam versi terkuat & teradilnya sebelum menanggapinya","Membuat versi paling lemah dari pendapat lawan agar lebih mudah dibantah di depan tim"],answer:1,explain:"Menanggapi versi terkuat pendapat lawan ('steelman') lebih menghormati & lebih meyakinkan daripada menyerang versi lemah ('strawman').",hint:"Versi terkuat & teradil, atau versi terlemah?"},
{n:23,type:"mcq",micro:"Perbedaan fakta vs perbedaan nilai",q:"Beda 'perbedaan pendapat soal fakta' & 'perbedaan soal nilai/prioritas':",options:["Keduanya sama saja & diselesaikan dengan cara yang sama, yaitu membuktikan siapa yang benar lewat debat sampai salah satu pihak kalah","Perbedaan nilai berarti salah satu pihak keliru, sehingga harus ada yang mengalah dan mengakui kesalahannya di depan tim, supaya diskusi selesai","Fakta bisa dicek (mis. 'acara mulai jam 8 atau 9'); nilai/prioritas soal apa yang lebih penting bagi tiap orang & butuh kompromi, bukan pembuktian"],answer:2,explain:"Perbedaan fakta diselesaikan dengan mengecek. Perbedaan nilai/prioritas diselesaikan dengan memahami & berkompromi.",hint:"Fakta dicek, nilai dikompromikan — atau sama saja?"},
{n:24,type:"mcq",micro:"Menghargai tanpa menyerah pada tekanan",q:"Menghormati pendapat mayoritas TIDAK berarti...",options:["Kamu harus mengubah pendapatmu hanya karena kamu sendirian; kamu tetap boleh menyuarakan pandangan berbeda dengan sopan","Kamu boleh menyabotase keputusan mayoritas diam-diam bila yakin pendapatmu lebih benar daripada tim, walau sudah kalah suara","Kamu wajib diam setelah kalah suara, dan tidak boleh lagi menyuarakan pandangan berbeda di dalam tim, karena itu sudah final"],answer:0,explain:"Menghormati mayoritas = menerima keputusan bersama setelah menyuarakan pandanganmu, bukan membungkam diri sendiri sebelum bicara.",hint:"Tetap boleh menyuarakan beda dengan sopan, atau harus ikut karena sendirian?"},
{n:25,type:"mcq",micro:"Perbedaan pendapat & ego",q:"Kadang orang mempertahankan pendapat bukan karena yakin benar, tapi karena...",options:["Perbedaan pendapat tidak ada hubungannya dengan ego, karena orang hanya berbeda dari fakta yang dipegangnya","Gengsi / tidak mau terlihat kalah — menyadari ini pada diri sendiri membantu kamu lebih terbuka berubah pikiran","Mereka benar-benar yakin pendapatnya paling tepat dan tidak mungkin keliru, sehingga tidak perlu berubah"],answer:1,explain:"Membedakan 'aku yakin ini benar' dari 'aku tidak mau kalah' membuatmu lebih jujur & terbuka dalam diskusi.",hint:"Gengsi bisa jadi alasan, atau tak ada hubungan dengan ego?"},
{n:26,type:"mcq",micro:"Menghargai lewat bahasa tubuh",q:"Bahasa tubuh yang menunjukkan kamu menghormati pendapat berbeda saat diskusi:",options:["Menyilangkan tangan dan memalingkan badan, supaya ia tahu kamu tidak setuju sebelum kalimatnya selesai","Melihat HP sambil orang berbicara, supaya bisa mengerjakan hal lain dan mendengar sekilas bagian penting","Menghadap pembicara, kontak mata, mengangguk saat mengikuti, tidak memutar mata atau menghela napas keras"],answer:2,explain:"Bahasa tubuh terbuka menyampaikan 'aku mendengarmu' bahkan saat kamu tidak setuju.",hint:"Menghadap + angguk, atau memalingkan / memutar mata?"},
{n:27,type:"tf",micro:"Tim seragam lebih baik?",q:"Benar atau Salah: Tim yang semua anggotanya selalu setuju & tidak pernah berbeda pendapat biasanya menghasilkan keputusan yang lebih baik daripada tim yang punya perbedaan pendapat.",answer:false,explain:"Sebaliknya, tim yang selalu setyju berisiko 'groupthink' — mengikuti satu suara tanpa memeriksa. Perbedaan pendapat yang dibahas baik menangkap kesalahan & memperkaya pilihan.",hint:"Selalu setuju = lebih baik, atau berisiko tidak diperiksa?"},
{n:28,type:"tf",micro:"Kritik ide bisa terasa seperti serangan pribadi",q:"Benar atau Salah: Bahkan kritik yang ditujukan pada ide (bukan orang) bisa terasa menyakitkan bagi si pengusul, jadi menyampaikannya dengan lembut & mengakui usahanya tetap penting.",answer:true,explain:"Orang sering merasa terikat pada idenya. Nada yang baik & pengakuan atas usaha membantu ia menerima kritik ide tanpa merasa diserang.",hint:"Kritik ide bisa tetap menyakitkan, atau tak berpengaruh?"},
{n:29,type:"mcq",micro:"Menghargai & mengubah pikiran",q:"Mengubah pendapatmu setelah mendengar argumen yang lebih baik adalah tanda...",options:["Kekuatan & keterbukaan berpikir, bukan kelemahan","Kekalahan memalukan karena berarti kalah berdebat","Tanda bahwa kamu tidak punya pendirian kuat"],answer:0,explain:"Orang yang tidak pernah berubah pikiran meski ada bukti lebih baik sebenarnya keras kepala, bukan berpendirian teguh.",hint:"Kekuatan & keterbukaan, atau kekalahan?"},
{n:30,type:"order",micro:"Diskusi perbedaan pendapat yang produktif",q:"Urutkan tahap diskusi tim yang punya dua pendapat berbeda.",items:["Tiap pihak menjelaskan pendapat & alasannya tanpa dipotong","Tiap pihak mengulang pendapat lawan sampai lawan berkata 'ya, itu maksudku'","Cari titik temu & poin yang disepakati kedua pihak","Timbang berdasarkan tujuan tim & putuskan bersama; semua dukung hasilnya"],answer:[0,1,2,3],explain:"Jelaskan → saling memantulkan → cari titik temu → putuskan bersama. Bukan adu keras sampai satu menyerah.",hint:"Apa yang dilakukan sebelum mencari titik temu?"},
{n:31,type:"mcq",micro:"Menghargai saat kamu yakin benar",q:"Kamu sangat yakin pendapatmu benar & anggota lain salah. Sikap yang tetap menghormati:",options:["Memaksakan pendapatmu tanpa mau mendengar sanggahan mereka, karena kamu yakin kamu benar & tidak ada gunanya mendengarkan hal yang salah","Sampaikan keyakinanmu dengan alasan & bukti, tetap dengarkan sanggahan mereka, & akui bila ada kemungkinan kamu keliru","Menyebut mereka bodoh karena tidak bisa melihat hal yang menurutmu 'sudah jelas', supaya mereka segera sadar dan mengikuti pendapatmu"],answer:1,explain:"Yakin benar bukan izin untuk merendahkan. Bahkan saat kamu benar, cara menyampaikan menentukan apakah orang mau menerima.",hint:"Alasan + tetap mendengar + akui kemungkinan keliru, atau merendahkan / memaksa?"},
{n:32,type:"tf",micro:"Perbedaan pendapat & pertemanan",q:"Benar atau Salah: Kalau kamu sering berbeda pendapat dengan seseorang, itu tanda kalian tidak cocok berteman & sebaiknya menjaga jarak.",answer:false,explain:"Sebaliknya, pertemanan yang sehat memberi ruang untuk berbeda. Yang merusak bukan perbedaannya, tapi cara yang tidak menghormati.",hint:"Bisa berteman + sering berbeda, atau perbedaan pasti merusak?"},
{n:33,type:"mcq",micro:"Menghargai lewat memberi waktu",q:"Anggota timmu butuh waktu memikirkan sebelum menyampaikan pendapat, sementara kamu cepat merespons. Sikap:",options:["Anggap diamnya berarti setuju dan lanjutkan keputusan, karena kalau ia keberatan tentu akan bilang sendiri","Desak dia menjawab saat itu juga di depan anggota lain, supaya ia belajar berpikir cepat dan merespons seperti kamu","Beri jeda & ruang; tanyakan pendapatnya secara khusus setelah diskusi berjalan sebentar — jangan anggap diamnya berarti setuju"],answer:2,explain:"Orang yang berpikir lebih lambat sering punya pendapat berharga. Memberi ruang menghormati cara berpikirnya.",hint:"Beri jeda + tanyakan khusus, atau anggap setuju / desak?"},
{n:34,type:"mcq",micro:"Perbedaan pendapat soal pembagian tugas",q:"Kamu & anggota lain tidak sepakat siapa yang seharusnya mengerjakan bagian sulit. Cara menyelesaikan:",options:["Bahas terbuka: pertimbangkan kekuatan, beban keseluruhan, & ketersediaan; cari pembagian yang dirasa adil kedua pihak","Yang suaranya lebih keras yang menentukan, karena itu cara paling cepat dan praktis supaya pekerjaan segera bisa dimulai tanpa berlarut-larut","Diam & kesal dengan pembagian yang ada tanpa mengatakan apa-apa, lalu mengerjakannya dengan setengah hati sambil menyimpan rasa tidak adil"],answer:0,explain:"Perbedaan soal pembagian diselesaikan dengan diskusi berbasis kriteria adil, bukan dominasi atau kekesalan terpendam.",hint:"Bahas berbasis kriteria adil, atau dominasi / pendam?"},
{n:35,type:"mcq",micro:"Menghargai sambil tetap jujur",q:"Menghormati pendapat berbeda TIDAK berarti kamu harus...",options:["Mendengarkan pendapat orang lain sungguh-sungguh sampai selesai","Berpura-pura setuju atau menyembunyikan kekhawatiran seriusmu","Menyampaikan pandanganmu dengan sopan dan jelas kepada tim"],answer:1,explain:"Menghormati = mendengar & menyampaikan dengan cara yang baik, bukan menyerahkan kejujuran. Kekhawatiran serius tetap perlu disuarakan.",hint:"Berpura-pura setuju, atau sopan + tetap jujur?"},
{n:36,type:"mcq",micro:"Konflik ide vs konflik pribadi",q:"Kalau perbedaan pendapat mulai bergeser jadi serangan pribadi ('kamu memang selalu begitu'), sikap yang menyehatkan:",options:["Balas menyerang pribadi orang itu dengan kata-kata sekeras itu, supaya ia tahu rasanya diperlakukan begitu","Tinggalkan diskusi tanpa bicara dan jangan kembali, supaya ia sadar ucapannya keterlaluan","Kembalikan ke isi: 'Ayo kita fokus ke idenya, bukan ke orangnya. Menurutku soal ide X...'"],answer:2,explain:"Mengarahkan kembali diskusi ke ide saat mulai jadi personal menjaga diskusi tetap produktif & hubungan tetap utuh.",hint:"Kembalikan ke isi, atau balas menyerang / pergi?"},
{n:37,type:"tf",micro:"Menghargai perbedaan bisa dilatih",q:"Benar atau Salah: Kemampuan menghadapi perbedaan pendapat dengan tenang adalah sifat bawaan; orang yang mudah defensif tidak bisa berubah.",answer:false,explain:"Sebaliknya, menahan reaksi awal, bertanya alasan, & memantulkan pendapat lawan semuanya keterampilan yang membaik dengan latihan sadar.",hint:"Bisa dilatih, atau bawaan tetap?"},
{n:38,type:"mcq",micro:"Menghargai pendapat orang yang lebih muda/kurang berpengalaman",q:"Anggota tim yang lebih muda / baru menyampaikan pendapat berbeda. Sikap:",options:["Timbang berdasarkan isi & alasannya, bukan berdasarkan usia/pengalaman; orang baru kadang melihat hal yang orang lama lewatkan","Abaikan pendapatnya karena dia belum berpengalaman dan belum banyak tahu cara kerja tim, jadi idenya kurang matang","Suruh dia diam dan belajar dulu dari anggota yang lebih lama, sebab pendapat berguna datang dari yang berpengalaman"],answer:0,explain:"Ide dinilai dari kualitasnya, bukan dari siapa yang mengucapkannya. 'Mata segar' sering menangkap hal yang orang terbiasa lewatkan.",hint:"Timbang isinya, atau tolak karena usia?"},
{n:39,type:"mcq",micro:"Perbedaan pendapat yang tidak perlu diselesaikan",q:"Beberapa perbedaan pendapat dalam tim...",options:["Menunjukkan tim gagal bekerja sama, karena tim yang baik harus sepakat tentang semua hal sampai yang terkecil, sehingga tim perlu bubar atau mengganti anggota","Tidak perlu diselesaikan sampai satu pihak menang — bisa dibiarkan (mis. selera pribadi yang tidak memengaruhi hasil) atau disepakati 'kita lihat berbeda & itu tidak apa-apa'","Harus diselesaikan dengan satu pemenang yang jelas, kalau tidak, tim akan terus bertengkar dan tidak bisa melanjutkan pekerjaannya, sehingga tenggat terlewat"],answer:1,explain:"Tidak semua perbedaan perlu resolusi. Yang memengaruhi hasil diputuskan; yang tidak bisa dibiarkan berdampingan.",hint:"Sebagian bisa dibiarkan berdampingan, atau semua harus ada pemenang?"},
{n:40,type:"open",micro:"Menganalisis diskusi yang buruk",q:"Dalam rapat, Sinta mengusulkan cara A, Bagas berkata 'Itu ide bodoh, jelas cara B lebih baik' tanpa alasan, Sinta membalas 'Kamu emang nggak pernah ngehargain orang', dan rapat berhenti dengan semua kesal. Jelaskan minimal 3 kesalahan dalam diskusi ini, lalu tulis ulang bagaimana Bagas & Sinta seharusnya menanggapi satu sama lain.",explain:"Jawaban baik menyebut minimal 3 kesalahan (menyerang ide dengan label tanpa alasan, klaim tanpa alasan, serangan pribadi balasan, tidak ada yang mengembalikan ke isi) dan menulis ulang tanggapan keduanya menjadi: memberi alasan spesifik, bertanya/mengakui poin lawan, dan bergerak ke solusi.",hint:"Cari: label tanpa alasan, klaim tanpa alasan, serangan pribadi, tak ada yang kembali ke isi. Tulis ulang dengan alasan + mengakui poin lawan + cari solusi.",sample:"Kesalahan: (1) Bagas menyerang ide dengan label ('ide bodoh') tanpa memberi alasan — ini merendahkan, bukan kritik yang membangun, dan tidak membantu tim menilai. (2) Bagas menyatakan cara B 'jelas lebih baik' juga tanpa alasan — jadi tidak ada yang bisa didiskusikan, hanya klaim. (3) Sinta membalas dengan serangan pribadi ('kamu nggak pernah ngehargain orang') — perbedaan ide bergeser jadi konflik karakter. (4) Tidak ada yang mengembalikan diskusi ke isi, jadi rapat berhenti tanpa hasil. Versi yang lebih baik: Bagas: 'Sinta, aku lihatnya agak beda. Menurutku cara B mungkin lebih cepat karena kita nggak perlu beli bahan tambahan. Tapi coba jelasin lagi, apa kelebihan cara A yang kamu lihat?' Sinta: 'Cara A memang butuh bahan tambahan, tapi hasilnya lebih tahan lama. Kalau soal kecepatan, poin kamu betul. Gimana kalau kita pakai cara B untuk bagian yang nggak kelihatan, dan cara A untuk bagian utama?' — keduanya memberi alasan, mengakui poin lawan, dan bergerak ke solusi gabungan."},
{n:41,type:"mcq",micro:"Skenario: kamu satu-satunya yang berbeda",q:"Seluruh tim setuju rencana X, hanya kamu yang khawatir. Sikap:",options:["Diam saja karena kamu sendirian, dan menganggap kekhawatiranmu kurang penting dibanding pendapat anggota lain, lalu menyimpannya sendiri","Terus menolak dan menghambat pekerjaan sampai tim menyerah dan mengubah rencana sesuai kekhawatiranmu, walau anggota lain sudah mendengarnya","Sampaikan kekhawatiranmu sekali dengan jelas & alasan spesifik; kalau tim tetap memilih X setelah mendengar, dukung keputusan itu"],answer:2,explain:"Menyuarakan pandangan minoritas sekali dengan jelas memenuhi tanggung jawabmu; setelah itu, mendukung keputusan tim.",hint:"Suarakan sekali lalu dukung, atau diam / menghambat?"},
{n:42,type:"mcq",micro:"Skenario: anggota memaksakan pendapatnya",q:"Seorang anggota selalu memaksakan pendapatnya & tidak mau mendengar yang lain. Sikap tim:",options:["Ingatkan dengan tenang bahwa keputusan diambil bersama & semua pendapat perlu didengar; minta ia menjelaskan alasannya lalu beri giliran yang lain","Menyerah dan ikut dia saja supaya tidak ada pertengkaran, walaupun pendapat anggota lain tidak dipertimbangkan lagi di rapat berikutnya","Semua ikut memaksakan pendapat masing-masing balik dengan suara keras, sampai yang paling kuat suaranya yang akhirnya dipilih untuk diikuti"],answer:0,explain:"Menegakkan 'semua didengar' dengan tenang lebih efektif daripada menyerah atau membalas dengan memaksa juga.",hint:"Tegakkan 'semua didengar', atau menyerah / balas memaksa?"},
{n:43,type:"mcq",micro:"Skenario: perbedaan pendapat & tenggat mepet",q:"Tim berdebat soal pendekatan & tenggat sudah dekat. Sikap yang produktif:",options:["Koordinator memutuskan sendirian tanpa mendengar pendapat anggota, supaya cepat selesai dan tidak ada perdebatan","Batasi waktu diskusi: 'Kita bahas 10 menit lagi, dengar dua sisi, lalu voting/putuskan. Kita nggak punya waktu debat panjang.'","Terus berdebat sampai salah satu menyerah, meskipun tenggat lewat, karena keputusan terbaik lahir dari debat panjang"],answer:1,explain:"Saat waktu terbatas, batasi diskusi lalu putuskan dengan mekanisme yang disepakati — bukan debat tanpa akhir atau keputusan sepihak.",hint:"Batasi waktu + putuskan dengan mekanisme, atau debat tanpa akhir / sepihak?"},
{n:44,type:"mcq",micro:"Skenario: menghargai pendapat soal hal yang kamu kuasai",q:"Kamu ahli di bidang tertentu & anggota lain (bukan ahli) punya pendapat berbeda. Sikap:",options:["Tolak langsung pendapatnya karena kamu ahli di bidang itu dan dia bukan, jadi pendapatnya kurang mendalam untuk dipertimbangkan","Merasa tersinggung karena ada yang berani berbeda pendapat di bidang keahlianmu, lalu menjawabnya dengan nada dingin dan singkat saja","Dengarkan pendapatnya — mungkin ia melihat dari sudut yang kamu lewatkan; jelaskan pertimbangan teknismu dengan sabar, bukan meremehkan"],answer:2,explain:"Keahlian bukan izin meremehkan. Orang non-ahli kadang mengajukan pertanyaan atau sudut pandang yang berharga.",hint:"Dengar + jelaskan sabar, atau tolak / tersinggung?"},
{n:45,type:"order",micro:"Menengahi dua anggota yang berbeda pendapat",q:"Urutkan cara menengahi dua teman tim yang berdebat sengit soal ide.",items:["Minta keduanya berhenti sejenak & bicara bergantian","Minta tiap orang menjelaskan idenya + alasannya, yang lain menyimak tanpa memotong","Minta tiap orang mengulang inti ide lawannya dengan adil","Bantu mereka menemukan titik temu atau opsi gabungan, lalu putuskan bersama tim"],answer:[0,1,2,3],explain:"Hentikan adu mulut → jelaskan bergantian → saling memantulkan → cari titik temu. Menengahi = memfasilitasi pemahaman.",hint:"Apa yang dilakukan sebelum mencari titik temu?"},
{n:46,type:"mcq",micro:"Skenario: pendapatmu diabaikan berulang",q:"Kamu beberapa kali menyampaikan pendapat berbeda tapi selalu diabaikan tanpa dibahas. Sikap:",options:["Sampaikan pola ini dengan tenang: 'Aku beberapa kali usul soal ini tapi belum sempat dibahas. Boleh kita pertimbangkan sebentar?'","Berhenti menyampaikan pendapat, karena terbukti tim tidak peduli dan usahamu hanya membuang tenaga serta waktu, walau kamu punya banyak ide","Menyampaikannya dengan marah dan menuduh tim sengaja mengabaikanmu, supaya mereka merasa bersalah dan memberi perhatian"],answer:0,explain:"Menyebut pola (diabaikan) + meminta ruang pembahasan, tenang & spesifik — bukan menyerah atau menuduh.",hint:"Sebut pola + minta ruang bahas, atau menyerah / menuduh?"},
{n:47,type:"mcq",micro:"Skenario: perbedaan pendapat soal nilai",q:"Timmu berbeda soal apakah proyek harus 'seaman mungkin' atau 'seambisius mungkin'. Ini perbedaan nilai/prioritas. Cara menyelesaikan:",options:["Yang paling banyak bicara di rapat yang menentukan, karena ia paling yakin dan paling siap mempertahankan pilihannya di depan anggota lain","Pahami apa yang penting bagi tiap pihak, lalu cari keseimbangan yang bisa diterima (mis. ambisius di bagian inti, aman di bagian lain)","Buktikan siapa yang 'benar' soal aman versus ambisius lewat debat, sampai salah satu pihak mengakui bahwa pandangannya tadi keliru"],answer:1,explain:"Perbedaan nilai tidak diselesaikan dengan pembuktian — melainkan dengan memahami prioritas tiap pihak & mencari keseimbangan.",hint:"Pahami prioritas + cari keseimbangan, atau buktikan siapa benar?"},
{n:48,type:"mcq",micro:"Skenario: anggota berubah pikiran",q:"Seorang anggota yang tadinya bersikeras dengan idenya, setelah mendengar diskusi, berkata 'oke, kalian benar, aku ganti pendapat'. Sikap tim:",options:["Ejek dia: 'Tuh kan, dari tadi sudah kubilang begitu,' supaya ia sadar seharusnya mendengarkanmu sejak awal","Anggap dia plin-plan dan tidak berpendirian, jadi pendapatnya nanti kurang dipercaya tim","Hargai keterbukaannya — jangan mengejek 'nah kan' atau membuatnya menyesal sudah berubah pikiran"],answer:2,explain:"Kalau tim mengejek orang yang berubah pikiran, orang lain jadi takut mengakui saat mereka keliru — diskusi jadi macet oleh gengsi.",hint:"Hargai keterbukaannya, atau ejek / anggap plin-plan?"},
{n:49,type:"mcq",micro:"Skenario: perbedaan pendapat dengan guru/pembimbing",q:"Kamu tidak setuju dengan arahan guru soal proyek. Cara menyampaikan dengan hormat:",options:["'Bu, boleh saya sampaikan pandangan berbeda? Menurut saya pendekatan lain mungkin lebih cocok karena... Tapi kami ikut keputusan Ibu.'","Mengabaikan arahan guru diam-diam & mengerjakan dengan cara sendiri, lalu tunjukkan hasilnya nanti supaya guru melihat bahwa pendekatanmu lebih baik","Membantah dengan keras di depan seluruh kelas supaya semua teman tahu bahwa arahan guru itu kurang tepat dan layak diperbaiki segera"],answer:0,explain:"Menyampaikan pandangan berbeda ke figur otoritas: minta izin, beri alasan, hormat, & menerima keputusan akhir.",hint:"Minta izin + alasan + hormat, atau abaikan / membantah keras?"},
{n:50,type:"open",micro:"Menyelesaikan perbedaan pendapat tim",q:"Timmu terbagi dua soal cara presentasi: Kelompok 1 (Ana, Budi) ingin presentasi formal dengan slide padat data; Kelompok 2 (Cici, Deni) ingin presentasi bercerita dengan sedikit slide. Keduanya punya alasan. Sebagai anggota kelima, rancang bagaimana kamu membantu tim menyelesaikan ini dengan menghormati kedua sisi (minimal 5 langkah).",explain:"Jawaban baik: minta tiap sisi menjelaskan + alasan bergantian, minta saling memantulkan sampai diakui, cari titik temu (tujuan sama), tawarkan opsi gabungan yang memakai kekuatan kedua pendekatan, timbang berdasarkan tujuan/kriteria & putuskan bersama, lalu semua mendukung & tegaskan ini soal ide bukan pribadi.",hint:"Jelaskan bergantian → saling memantulkan → titik temu (tujuan sama) → opsi gabungan → timbang berdasarkan tujuan & putuskan bersama → semua dukung.",sample:"(1) Kumpulkan tim & minta tiap kelompok menjelaskan pendekatan mereka + alasannya secara bergantian, tanpa dipotong. Ana-Budi: data padat meyakinkan penilai bahwa riset kami serius. Cici-Deni: cerita membuat penonton ingat pesan utama & tidak bosan. (2) Minta tiap kelompok mengulang inti pendekatan kelompok lain dengan adil, sampai kelompok itu berkata 'ya, itu maksud kami' — supaya semua benar-benar memahami sisi lawan, bukan versi karikaturnya. (3) Cari titik temu: sebenarnya keduanya sama-sama ingin presentasi yang meyakinkan & diingat. Perbedaannya soal cara. (4) Tawarkan opsi gabungan: buka dengan cerita singkat yang menarik (usul Kelompok 2), lalu sampaikan 2-3 poin data terpenting di slide yang bersih & jelas (bukan padat — kompromi), tutup dengan kembali ke cerita. Ini memakai kekuatan kedua pendekatan. (5) Kalau masih ada ketidaksepakatan soal detail, timbang berdasarkan tujuan (nilai + kesan penonton) & kriteria penilaian guru, lalu putyskan bersama (voting atau serahkan keputusan final ke penanggung jawab presentasi dengan masukan semua). (6) Setelah diputuskan, semua mendukung & memberi yang terbaik; tegaskan bahwa perbedaan tadi soal ide, bukan pribadi."},
{n:51,type:"mcq",micro:"Skenario: menghargai lewat memberi kredit ide",q:"Ide gabungan tim sebenarnya berawal dari usul anggota yang tadinya kalah suara. Sikap yang menghormati:",options:["Tidak menyebut siapa yang memberi usul awal, karena yang penting hasilnya, bukan siapa yang pertama memunculkan ide","Akui: 'Ide ini sebenarnya berkembang dari usul [nama] tadi.' — mengakui kontribusi meski usul awalnya tidak langsung dipakai","Klaim ide gabungan itu sebagai milik mayoritas, karena merekalah yang memilih dan menyempurnakannya sampai bisa dipakai"],answer:1,explain:"Menghargai berarti mengakui kontribusi orang bahkan saat usul awalnya harus dimodifikasi. Itu membuat orang tetap mau berkontribusi.",hint:"Akui asal idenya, atau klaim mayoritas / abaikan?"},
{n:52,type:"tf",micro:"Menghargai perbedaan menguatkan tim",q:"Benar atau Salah: Tim di mana anggota takut menyampaikan pendapat berbeda (karena bisa diejek) biasanya membuat keputusan lebih cepat & lebih baik.",answer:false,explain:"Sebaliknya, rasa takut membuat informasi & sudut pandang penting disembunyikan. Tim yang aman untuk berbeda membuat keputusan lebih baik & anggotanya lebih terlibat.",hint:"Menguatkan tim, atau melemahkan?"},
{n:53,type:"mcq",micro:"Skenario: perbedaan pendapat soal fakta",q:"Kamu & anggota lain berbeda soal 'kapan acara sebenarnya dimulai'. Cara menyelesaikan:",options:["Berdebat sampai satu pihak menyerah dan mengaku keliru, karena fakta terbukti dari siapa yang bertahan paling lama","Yang lebih yakin dan lebih keras bicaranya dianggap benar, sehingga yang ragu cukup mengikuti tanpa mengecek","Cek sumbernya (pengumuman resmi, tanya panitia) — perbedaan fakta diselesaikan dengan verifikasi, bukan debat"],answer:2,explain:"Perbedaan tentang fakta yang bisa dicek diselesaikan dengan mengecek, bukan dengan adu keyakinan.",hint:"Cek sumbernya, atau debat / adu yakin?"},
{n:54,type:"mcq",micro:"Skenario: kamu terpancing merendahkan",q:"Dalam diskusi, kamu tergoda berkata 'ide kamu konyol'. Sebelum mengucapkannya:",options:["Tahan, ubah jadi: 'Aku khawatir soal X di ide itu. Bisa dijelasin gimana ngatasinnya?'","Ucapkan saja karena 'jujur', walau orang itu akan tersinggung di depan teman-teman","Diam sambil memutar mata, lalu mengeluh tentang ide itu kepada teman sebelah"],answer:0,explain:"Mengubah cemoohan jadi pertanyaan/kekhawatiran spesifik menjaga diskusi produktif & hubungan utuh.",hint:"Ubah jadi kekhawatiran spesifik, atau ucapkan / memutar mata?"},
{n:55,type:"mcq",micro:"Skenario: setelah keputusan, ada yang masih tidak puas",q:"Keputusan tim sudah diambil lewat mekanisme yang disepakati, tapi satu anggota masih terus mengungkit ketidaksetujuannya. Sikap tim:",options:["Memusuhi dia karena terus menolak keputusan, lalu mengabaikan kekhawatirannya dalam rapat berikutnya di depan semua anggota","Ingatkan dengan tenang: 'Kita udah putuskan bareng lewat cara yang kita sepakati. Kekhawatiranmu tercatat. Sekarang ayo kita jalankan.'","Membatalkan keputusan karena dia mengeluh, lalu mengulang pembahasan dari awal bersama seluruh anggota tim, walau tenggat dekat"],answer:1,explain:"Menghormati pendapat berbeda punya batas waktu: setelah keputusan adil diambil, semua diharapkan mendukung. Kekhawatiran boleh dicatat.",hint:"Ingatkan keputusan sudah adil + kekhawatiran tercatat, atau batalkan / musuhi?"},
{n:56,type:"mcq",micro:"Skenario: menghargai perbedaan di grup chat",q:"Anggota menyampaikan pendapat berbeda di grup chat & beberapa membalas dengan emoji tertawa & sindiran. Sikap yang menyehatkan:",options:["Ikut menyindir bersamanya supaya suasana cair, lalu bergantian membuat candaan tentang kekhawatiran soal waktu itu, di depan semua anggota","Diam dan membiarkan sindiran itu berlanjut, karena menegur dianggap merusak suasana dan memperpanjang konflik, apalagi saat rapat sedang singkat","Kembalikan ke isi & nada hormat: 'Poin [nama] menarik. Menurut kalian gimana soal kekhawatiran soal waktunya?' — jangan biarkan sindiran jadi norma"],answer:2,explain:"Di chat, sindiran mudah menular. Mengembalikan diskusi ke isi & nada hormat menjaga ruang tetap aman untuk berbeda pendapat.",hint:"Kembalikan ke isi & hormat, atau ikut menyindir / diam?"},
{n:57,type:"tf",micro:"Menghargai bukan berarti pendapat semua sama nilainya",q:"Benar atau Salah: Menghormati pendapat orang berarti mendengarkannya sungguh-sungguh — tetapi pendapat yang didukung alasan & bukti kuat tetap layak lebih dipertimbangkan daripada pendapat tanpa dasar.",answer:true,explain:"Menghargai orangnya tidak sama dengan menganggap semua pendapat sama kuatnya. Diskusi yang baik tetap menimbang kualitas argumen.",hint:"Semua pendapat sama nilainya, atau dengar semua tapi timbang kualitas argumen?"},
{n:58,type:"mcq",micro:"Skenario: perbedaan pendapat jangka panjang di organisasi",q:"Di organisasi/klub, dua kelompok terus berbeda pandangan soal arah. Sikap yang sehat:",options:["Adakan forum untuk mendengar kedua sisi secara terbuka, cari kompromi atau keputusan lewat mekanisme yang disepakati, & jaga agar perbedaan tidak jadi permusuhan antar kelompok","Salah satu kelompok mendominasi dan mengabaikan yang lain, supaya keputusan cepat diambil dan organisasi tetap bergerak maju, dan kelompok lain diminta menyesuaikan","Organisasi dibiarkan pecah tanpa dibicarakan lebih dulu, karena perbedaan arah yang terlalu besar memang tidak mungkin dipertemukan kembali, lalu kelompok baru dibentuk"],answer:0,explain:"Perbedaan pandangan jangka panjang butuh forum terbuka, mekanisme keputusan yang adil, & usaha menjaga hubungan antar kelompok.",hint:"Forum terbuka + mekanisme adil + jaga hubungan, atau dominasi / pecah?"},
{n:59,type:"mcq",micro:"Skenario: kamu menyadari kamu yang keliru",q:"Di tengah debat, kamu sadar pendapat lawan lebih tepat. Sikap yang menghormati (diri sendiri & tim):",options:["Diam saja & pura-pura tidak berubah pikiran, supaya tidak terlihat kalah dan tidak perlu mengakui bahwa pendapat lawan memang lebih tepat","Akui dengan jujur: 'Setelah dengar penjelasanmu, aku setuju, pendapatku tadi kurang tepat.' — tanpa berlebihan menyalahkan diri","Terus mempertahankan pendapatmu demi gengsi dan nama baik di depan tim, walaupun dalam hati kamu tahu pendapat lawan lebih tepat"],answer:1,explain:"Mengakui saat kamu keliru membuat diskusi tim lebih jujur & mendorong orang lain juga berani mengaku keliru.",hint:"Akui jujur, atau ngotot demi gengsi / diam?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu ketua tim 6 orang. Dalam sebuah rapat penting, tim terpecah tajam menjadi dua kubu soal keputusan besar, suasana mulai panas, dan beberapa mulai saling menyindir. Rancang bagaimana kamu memimpin tim melewati perbedaan pendapat ini dengan menghormati semua pihak & sampai ke keputusan (minimal 6 langkah).",explain:"Jawaban baik: hentikan saat panas + tetapkan aturan diskusi hormat, beri waktu setara tiap sisi menjelaskan + alasan (dicatat terlihat), wajibkan saling memantulkan sampai diakui, cari titik temu (tujuan sama), eksplorasi opsi gabungan/pembagian, timbang berdasarkan tujuan & batasan lalu putuskan lewat mekanisme disepakati, tegaskan semua dukung + kekhawatiran tercatat, dan follow up pribadi ke yang kecewa.",hint:"Hentikan+aturan diskusi → waktu setara+catat → saling memantulkan → titik temu → opsi gabungan → timbang+putuskan lewat mekanisme → semua dukung → follow up yang kecewa.",sample:"(1) Hentikan sejenak saat suasana mulai panas: 'Oke, kita berhenti dulu bentar. Ini keputusan penting dan wajar kita punya pandangan beda. Ayo kita bahas dengan cara yang bikin semua kedengeran.' (2) Tetapkan aturan diskusi singkat: bicara bergantian, tidak menyindir atau menyerang pribadi, fokus pada ide dan alasannya. (3) Beri tiap kubu waktu setara untuk menjelaskan pandangan + alasannya, sementara yang lain menyimak tanpa memotong; aku (atau pencatat) menulis poin-poin utama tiap sisi supaya terlihat. (4) Minta tiap kubu mengulang inti pandangan kubu lain dengan adil sampai kubu itu setuju 'ya, itu maksud kami' — ini memaksa semua benar-benar memahami sisi lawan. (5) Cari titik temu: apa yang sebenarnya sama-sama diinginkan kedua kubu (biasanya tujuannya sama, caranya beda)? Tuliskan hal yang sudah disepakati. (6) Eksplorasi opsi: adakah pilihan ketiga yang menggabungkan kekuatan kedua sisi, atau cara membagi sehingga keduanya sebagian terpenuhi? (7) Kalau tetap harus memilih, timbang opsi berdasarkan tujuan tim & batasan (waktu, sumber daya, risiko), lalu putuskan lewat mekanisme yang disepakati (voting atau keputusan ketua dengan masukan semua). (8) Setelah diputuskan, tegaskan: 'Kekhawatiran semua sudah dicatat. Keputusan ini diambil bareng lewat cara yang kita sepakati. Sekarang kita semua dukung dan kasih yang terbaik.' (9) Setelah rapat, hubungi anggota yang tampak paling kecewa secara pribadi untuk memastikan hubungan tetap baik & mereka tetap merasa dihargai."},
{n:61,type:"mcq",micro:"Mengapa perbedaan pendapat berharga",q:"Mengapa tim yang punya perbedaan pendapat (yang dibahas baik) sering membuat keputusan lebih baik?",options:["Karena perbedaan pendapat membuat orang bekerja lebih keras sambil kesal, dan kemarahan itu menghasilkan hasil lebih bagus","Perbedaan pendapat tidak memengaruhi kualitas keputusan, sebab keputusan terbaik sama saja berapa pun jumlah orang yang membahasnya","Perbedaan memaksa tim menimbang beberapa sisi, menguji asumsi, & menangkap risiko atau peluang yang satu sudut pandang lewatkan"],answer:2,explain:"Keputusan yang tidak pernah ditantang sering menyimpan lubang. Perbedaan pendapat adalah 'pengecekan' gratis.",hint:"Menimbang beberapa sisi & menguji asumsi, atau tak berpengaruh?"},
{n:62,type:"mcq",micro:"Mengapa menyerang orang gagal",q:"Mengapa menyerang pribadi ('kamu memang bodoh') saat berbeda pendapat merusak diskusi?",options:["Orang yang merasa diserang beralih ke bertahan diri & tidak lagi mendengar isi; masalah inti tidak terselesaikan & hubungan rusak","Karena itu melanggar aturan sekolah dan bisa membuat pelakunya dihukum, bukan karena pengaruhnya pada jalannya diskusi atau kerja sama tim","Justru membuat orang cepat setuju karena mereka takut dan malu, sehingga diskusi cepat selesai & keputusan lebih mudah diambil bersama"],answer:0,explain:"Kritik ide bisa didengar; serangan pribadi menutup telinga & membakar jembatan.",hint:"Memicu pertahanan & merusak hubungan, atau membuat cepat setuju?"},
{n:63,type:"tf",micro:"Groupthink",q:"Benar atau Salah: 'Groupthink' terjadi ketika anggota tim menahan pendapat berbeda demi keharmonisan, sehingga tim mengambil keputusan buruk yang sebenarnya diragukan banyak orang secara diam-diam.",answer:true,explain:"Keharmonisan palsu (semua diam & mengangguk) berbahaya. Menyuarakan keraguan dengan hormat justru melindungi tim.",hint:"Groupthink = menahan pendapat demi harmoni, atau tim yang sehat?"},
{n:64,type:"mcq",micro:"Menilai diskusi yang sehat",q:"Tanda diskusi tentang perbedaan pendapat berjalan sehat:",options:["Anggota langsung setuju tanpa membahas apa-apa, sehingga keputusan cepat diambil dan waktu tidak terbuang berdebat lama","Fokus pada ide & alasan, semua merasa didengar, orang boleh berubah pikiran tanpa diejek, & hubungan tetap baik setelahnya","Yang paling keras suaranya menang di setiap keputusan, sehingga tim tidak perlu repot menimbang pendapat anggota, dan debat cepat selesai"],answer:1,explain:"Diskusi sehat = pertukaran ide yang jujur di mana orang tetap aman & dihargai, apa pun hasilnya.",hint:"Fokus ide + semua didengar + hubungan utuh, atau yang keras menang / langsung setuju?"},
{n:65,type:"mcq",micro:"Mengapa memantulkan pendapat lawan membantu",q:"Meminta tiap pihak mengulang pendapat lawan sampai lawan setuju 'itu maksudku' berguna karena...",options:["Membuat diskusi lebih lama tanpa manfaat, karena kedua pihak hanya mengulang kalimat yang sama tanpa keputusan yang jelas","Memaksa salah satu pihak menyerah karena tak bisa membantah lagi, sehingga pihak lain menang tanpa perlu berpikir","Memastikan kedua pihak benar-benar memahami perbedaan yang sebenarnya, bukan berdebat dengan versi karikatur satu sama lain"],answer:2,explain:"Banyak 'perbedaan pendapat' sebenarnya salah paham. Memantulkan mengungkap apakah perbedaannya nyata & di mana persisnya.",hint:"Memastikan paham perbedaan sebenarnya, atau memperlama?"},
{n:66,type:"tf",micro:"Menghormati = tidak boleh tegas?",q:"Benar atau Salah: Menghormati pendapat orang lain berarti kamu tidak boleh menyampaikan ketidaksetujuanmu dengan tegas.",answer:false,explain:"Sebaliknya, kamu bisa sangat tegas soal ISI ('aku benar-benar tidak setuju karena X') sambil tetap hormat soal CARA (nada tenang, fokus ide, mengakui usaha). Tegas dan hormat bisa bersama.",hint:"Hormat = tidak boleh tegas, atau bisa tegas isi + hormat cara?"},
{n:67,type:"mcq",micro:"Perbedaan pendapat & kepercayaan tim",q:"Mengapa tim yang bisa membahas perbedaan pendapat dengan hormat justru lebih saling percaya?",options:["Anggota tahu bahwa bila mereka punya keraguan, mereka bisa menyuarakannya & akan didengar — bukan harus menebak apakah aman","Karena anggota tidak berbeda pendapat, sehingga kepercayaan terbentuk dari kesamaan pandangan, bukan dari cara membahas perbedaan","Perbedaan pendapat tidak memengaruhi kepercayaan, sebab rasa percaya hanya ditentukan lamanya orang saling mengenal satu sama lain"],answer:0,explain:"Kepercayaan tumbuh dari 'aku bisa jujur di sini'. Tim yang menghukum perbedaan mengajarkan anggota untuk menyembunyikan.",hint:"Anggota tahu keraguan akan didengar, atau tak berpengaruh?"},
{n:68,type:"mcq",micro:"Perbedaan pendapat yang berbasis identitas/keyakinan",q:"Untuk perbedaan yang menyentuh keyakinan atau identitas pribadi (agama, budaya, nilai keluarga), sikap dalam kerja tim:",options:["Menganggap anggota yang berbeda keyakinan tidak bisa diajak bekerja sama, lalu menempatkan mereka di bagian yang terpisah dari anggota lainnya","Fokus pada tugas & tujuan bersama; hormati bahwa perbedaan itu ada tanpa harus 'memenangkannya'; hindari memaksakan keyakinan pribadi ke anggota lain","Perdebatkan perbedaan keyakinan itu sampai salah satu pihak 'kalah' & mengakui bahwa keyakinan pihak yang lain memang lebih benar dan layak diikuti"],answer:1,explain:"Sebagian perbedaan tidak untuk 'diselesaikan' dalam tim. Yang penting: saling menghormati & fokus pada tujuan bersama.",hint:"Hormati + fokus tujuan bersama, atau perdebatkan sampai menang / tolak kerja sama?"},
{n:69,type:"mcq",micro:"Menilai apakah suatu perbedaan perlu diperjuangkan",q:"Sebelum memperjuangkan pendapatmu dengan keras, pertimbangkan:",options:["Perjuangkan setiap pendapat sekuat mungkin sampai menang, karena menyerah sedikit berarti kamu tidak punya pendirian di tim","Jangan menyampaikan pendapat supaya tidak ada perbedaan, karena perbedaan berakhir dengan pertengkaran di dalam tim dan merusak kekompakan","Seberapa besar dampaknya pada hasil? Apakah ini soal fakta/prinsip penting, atau selera/detail kecil? Apakah aku yakin atau hanya tidak mau kalah?"],answer:2,explain:"Memilih 'pertempuran' dengan bijak — memperjuangkan yang penting, melepaskan yang kecil — membuat suaramu lebih dihargai saat benar-benar dibutuhkan.",hint:"Timbang dampak & motivasi, atau perjuangkan semua / diam semua?"},
{n:70,type:"order",micro:"Dari terpancing ke tanggapan yang menghormati",q:"Urutkan proses saat kamu terpancing ingin merendahkan pendapat orang.",items:["Kenali reaksimu: dada panas, ingin berkata 'itu konyol'","Beri jeda: tarik napas, tahan respons","Cari: apa yang mungkin masuk akal / benar dari pendapat itu?","Sampaikan kekhawatiranmu sebagai pertanyaan/poin spesifik soal ide, dengan nada tenang"],answer:[0,1,2,3],explain:"Kenali → jeda → cari sisi baik → sampaikan sebagai poin spesifik. Jeda memisahkan cemoohan dari tanggapan yang berguna.",hint:"Apa yang perlu disadari sebelum memberi jeda?"},
{n:71,type:"mcq",micro:"Perbedaan pendapat & pembelajaran",q:"Bekerja dalam tim yang sering berbeda pendapat (dengan hormat) membuat kamu...",options:["Terbiasa menimbang sudut pandang lain, menguji asumsimu sendiri, & lebih fleksibel dalam berpikir","Bingung dan tidak berkembang, sebab banyaknya pendapat berbeda membuatmu tidak bisa menentukan yang benar","Kehilangan pendirian, karena terlalu sering mendengarkan orang lain sampai tidak punya pendapat sendiri"],answer:0,explain:"Berlatih menghadapi perbedaan pendapat melatih pikiran untuk lebih terbuka & teliti — keterampilan berharga di mana pun.",hint:"Melatih berpikir fleksibel & teliti, atau membuat bingung?"},
{n:72,type:"tf",micro:"Menghormati perbedaan lintas budaya",q:"Benar atau Salah: Cara menyampaikan ketidaksetujuan sama persis di semua budaya & keluarga, jadi tidak perlu khawatir salah menafsir maksud orang.",answer:false,explain:"Sebaliknya, sebagian budaya/keluarga sangat langsung, sebagian sangat halus. Yang halus bisa terlewat oleh orang dari budaya langsung; yang langsung bisa terasa kasar bagi yang lain. Menyadari ini mengurangi salah paham.",hint:"Cara menyampaikan beda antar budaya, atau universal?"},
{n:73,type:"mcq",micro:"Menghormati & tanggung jawab",q:"Menghormati pendapat berbeda datang dengan tanggung jawab, yaitu...",options:["Mengalah pada pendapat orang lain supaya suasana tenang dan tidak terjadi konflik di tim","Menyampaikan pendapatmu sendiri dengan jujur & beralasan juga — bukan hanya mendengar lalu diam","Menyembunyikan pendapatmu supaya tidak dianggap berbeda, lalu mengikuti arus kelompok saja"],answer:1,explain:"Diskusi yang sehat butuh semua pihak menyumbang pandangan. 'Menghormati' bukan berarti menghilangkan suaramu sendiri.",hint:"Sampaikan pandanganmu juga, atau hanya dengar lalu diam?"},
{n:74,type:"mcq",micro:"Menilai 'debat kusir'",q:"'Debat kusir' (berdebat hanya untuk menang, bukan mencari kebenaran) dikenali dari...",options:["Orang saling mengakui poin yang benar dari lawan, bersedia mengubah pendapat, & bersama-sama mencari solusi yang paling baik bagi tim","Diskusi berlangsung tenang dan fokus pada ide, dengan anggota bergantian bicara, mendengarkan, dan berusaha memahami sudut pandang lain","Orang tidak pernah mengakui poin lawan, mengganti-ganti argumen saat kalah, menyerang pribadi, & tujuannya jelas menang bukan memahami"],answer:2,explain:"Kalau lawan bicara tidak pernah bergerak & hanya mau menang, kadang lebih baik menghentikan diskusi daripada terus terpancing.",hint:"Tidak pernah mengakui + tujuannya menang, atau saling mengakui + cari solusi?"},
{n:75,type:"tf",micro:"Perbedaan pendapat setelah keputusan",q:"Benar atau Salah: Setelah tim mengambil keputusan lewat proses yang adil & disepakati, anggota yang tadinya tidak setuju diharapkan tetap mendukung & menjalankan keputusan itu dengan baik ('tidak setuju, tetap komit').",answer:true,explain:"Menghormati proses berarti menerima hasilnya. Terus menyabotase atau mengungkit setelah keputusan adil merusak tim.",hint:"Dukung setelah proses adil, atau boleh sabotase / ungkit terus?"},
{n:76,type:"mcq",micro:"Perbedaan pendapat & kualitas pemimpin",q:"Pemimpin tim yang baik terhadap perbedaan pendapat...",options:["Sengaja mengundang pandangan berbeda ('ada yang lihat risiko di rencana ini?'), tidak menghukum yang berbeda, & memfasilitasi keputusan yang adil","Menekan semua anggota yang tidak setuju dengannya supaya keputusan cepat diambil, serta supaya tim terlihat kompak dan tidak banyak membantah","Menghindari keputusan agar tak ada yang kecewa, sehingga tim terus menunda dan tidak kunjung menentukan arah pekerjaannya selama proyek"],answer:0,explain:"Pemimpin yang hanya dikelilingi orang yang setuju kehilangan informasi penting. Mengundang perbedaan adalah tanda pemimpin kuat.",hint:"Mengundang perbedaan + memfasilitasi, atau menekan / menghindari keputusan?"},
{n:77,type:"mcq",micro:"Perbedaan pendapat & rasa memiliki",q:"Anggota yang pendapatnya didengar & dipertimbangkan (meski tidak selalu dipakai) cenderung...",options:["Tidak peduli pada hasil akhir proyek, karena mereka hanya ingin didengar saja","Lebih mendukung keputusan akhir & lebih terlibat, karena merasa jadi bagian dari proses","Kecewa dan menarik diri dari tim karena pendapatnya tidak dipakai"],answer:1,explain:"Rasa 'aku didengar' membuat orang menerima hasil yang bukan pilihannya jauh lebih lapang.",hint:"Lebih mendukung & terlibat, atau kecewa & menarik diri?"},
{n:78,type:"mcq",micro:"Menghormati vs toleransi terhadap yang menyakiti",q:"Menghormati perbedaan pendapat TIDAK berarti tim harus menoleransi...",options:["Pandangan berbeda soal strategi, karena perbedaan strategi merusak kekompakan tim","Kritik sopan dengan alasan jelas, karena semua kritik menyakiti perasaan anggota","Ucapan yang menghina, merendahkan kelompok tertentu, atau menyerang pribadi anggota"],answer:2,explain:"Ada batas: menghormati perbedaan ide berbeda dari membiarkan perilaku yang melukai atau merendahkan orang.",hint:"Menghina & merendahkan orang, atau pandangan berbeda soal strategi?"},
{n:79,type:"mcq",micro:"Perbedaan pendapat & waktu",q:"Kapan sebuah perbedaan pendapat sebaiknya dibiarkan tidak terselesaikan (agree to disagree)?",options:["Bila tidak memengaruhi hasil/tindakan yang perlu diambil, atau bila lebih menyangkut selera/nilai pribadi yang tidak perlu diseragamkan","Hampir tidak mungkin — semua perbedaan pendapat harus diselesaikan sampai ada pemenang jelas, agar tidak menggantung di tim","Setiap kali — perbedaan pendapat sebaiknya tidak diselesaikan, karena membahasnya hanya menimbulkan pertengkaran baru di antara anggota"],answer:0,explain:"Menghabiskan energi menyelesaikan perbedaan yang tidak penting membuang waktu & bisa merusak hubungan tanpa manfaat.",hint:"Bila tidak memengaruhi hasil / soal selera, atau selalu harus ada pemenang?"},
{n:80,type:"open",micro:"Membandingkan dua tim",q:"Tim A: anggota yang berbeda pendapat langsung diejek 'sok tahu', semua akhirnya diam & mengikuti ketua, keputusan diambil cepat tapi ternyata punya lubang besar yang beberapa anggota sebenarnya sudah lihat. Tim B: perbedaan pendapat didengar, dibahas dengan fokus ide, keputusan lebih lambat tapi lebih matang, anggota yang kalah suara tetap mendukung. Jelaskan mengapa Tim B lebih sehat & kemungkinan lebih sukses jangka panjang (minimal 4 alasan), dan 1 kelemahan pendekatan Tim B yang perlu dikelola.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih sehat (keputusan lebih matang/teruji, informasi tidak disembunyikan karena aman, anggota lebih terlibat & mendukung, hubungan terjaga karena fokus ide, tim belajar & membaik) dan 1 kelemahan yang perlu dikelola (diskusi bisa berlarut/lambat — perlu batas waktu & mekanisme keputusan).",hint:"Alasan B: keputusan teruji, info tidak disembunyikan, anggota terlibat, hubungan terjaga, tim membaik. Kelemahan: bisa lambat/berlarut — perlu batas waktu + mekanisme.",sample:"Tim B lebih sehat & kemungkinan lebih sukses karena: (1) Keputusan Tim B lebih matang karena diuji dari beberapa sudut — lubang seperti yang dialami Tim A lebih mungkin ketahuan sebelum terlambat. (2) Anggota Tim B merasa aman menyuarakan keraguan, jadi informasi penting tidak disembunyikan; di Tim A, orang yang melihat masalah memilih diam karena takut diejek. (3) Anggota Tim B lebih terlibat dan mendukung keputusan akhir karena merasa didengar, sementara anggota Tim A hanya patuh di permukaan dan mungkin diam-diam tidak berkomitmen. (4) Hubungan dalam Tim B tetap baik karena perbedaan difokuskan pada ide, bukan pribadi; di Tim A, ejekan 'sok tahu' merusak kepercayaan dan membuat orang enggan berkontribusi lagi. (5) Dalam jangka panjang, Tim B belajar dan makin efektif tiap proyek, sedangkan Tim A akan terus membuat keputusan berlubang karena tidak ada yang berani mengoreksi. Kelemahan pendekatan Tim B yang perlu dikelola: diskusi bisa berlarut-larut dan lambat kalau tidak dibatasi. Tim B perlu menetapkan batas waktu diskusi dan mekanisme keputusan yang jelas, supaya menghargai perbedaan pendapat tidak berubah menjadi kebuntuan."},
{n:81,type:"mcq",micro:"Kasus: perbedaan pendapat & anggota yang tidak pernah mengalah",q:"Seorang anggota tidak pernah mau bergerak dari pendapatnya, tidak memberi alasan baru, & tujuannya jelas hanya menang. Sikap tim:",options:["Terus berdebat tanpa akhir sampai ia mau mengubah pendapatnya, walaupun tenggat dekat dan anggota lain kelelahan menunggu, demi menjaga kekompakan tim","Setelah memberinya kesempatan penuh menjelaskan & didengar, jalankan mekanisme keputusan yang disepakati; diskusi tidak bisa disandera satu orang yang menolak semua","Menuruti dia agar diskusi cepat selesai dan suasana tenang, walaupun alasannya tidak berubah, dan mengabaikan keberatan anggota lain demi menjaga tenggat"],answer:1,explain:"Menghormati berarti mendengar sungguh-sungguh; tapi tim tidak bisa lumpuh karena satu orang menolak proses. Setelah didengar, keputusan diambil lewat mekanisme.",hint:"Dengar penuh lalu jalankan mekanisme, atau selalu turuti / debat tanpa akhir?"},
{n:82,type:"mcq",micro:"Kasus: kamu diminta memihak",q:"Dua teman tim berbeda pendapat & masing-masing mendesakmu 'kamu di pihak siapa?'. Sikap:",options:["Pilih pihak teman yang lebih dekat denganmu, lalu bantu dia meyakinkan anggota lain bahwa idenya yang paling tepat untuk tim, sebab itu menjaga persahabatan","Menghindari rapat itu dan menyerahkan keputusan kepada kedua pihak, supaya kamu tidak terlibat dalam konflik antar teman, lalu menunggu hasilnya saja","'Aku nggak mau ini jadi soal pihak. Aku dengar dua-duanya. Poin [nama] soal X kuat, poin [nama] soal Y juga. Gimana kalau kita...' — nilai berdasarkan ide, bukan orang"],answer:2,explain:"Perbedaan pendapat tim bukan pertandingan tim. Menolak membingkainya sebagai 'pihak' & menilai berdasarkan ide menjaga tim tetap satu.",hint:"Nilai berdasarkan ide + tolak 'pihak', atau pilih teman dekat / kabur?"},
{n:83,type:"tf",micro:"Refleksi: menghargai perbedaan = kekuatan tim",q:"Benar atau Salah: Tim yang sering menghadapi perbedaan pendapat pasti tim yang bermasalah; tim yang benar-benar matang hampir tidak pernah berbeda pendapat.",answer:false,explain:"Sebaliknya, tim lemah pecah atau membisu saat berbeda pendapat. Tim matang & kuat justru menghadapinya dengan hormat & menggunakannya untuk keputusan lebih baik.",hint:"Tanda tim matang, atau tanda tim bermasalah?"},
{n:84,type:"mcq",micro:"Kasus: menghargai perbedaan saat kamu punya kuasa",q:"Kamu ketua & punya wewenang memutuskan. Seorang anggota junior menyampaikan pandangan berbeda dengan sopan. Sikap yang menghormati:",options:["Dengarkan sungguh-sungguh & timbang isinya; jelaskan alasan keputusanmu bila berbeda; jangan pakai wewenang untuk membungkam atau mempermalukannya","Tolak langsung pendapatnya karena kamu yang berwenang memutuskan, & anggota junior sebaiknya belajar mengikuti arahan tanpa perlu berpendapat","Anggap dia menantang otoritasmu sebagai ketua, lalu tegur dia di depan semua anggota supaya tidak ada lagi yang berani melakukan hal serupa"],answer:0,explain:"Wewenang untuk memutuskan bukan izin mengabaikan atau membungkam pandangan berbeda. Pemimpin yang mendengar membuat keputusan lebih baik.",hint:"Dengar + jelaskan alasan, atau tolak karena berwenang / anggap menantang?"},
{n:85,type:"order",micro:"Menyelesaikan perbedaan pendapat yang menyentuh nilai",q:"Urutkan cara tim menyelesaikan perbedaan yang menyangkut nilai/prioritas (mis. 'utamakan kecepatan' vs 'utamakan kualitas').",items:["Akui bahwa ini perbedaan prioritas, bukan soal siapa yang 'benar'","Minta tiap pihak menjelaskan mengapa prioritas itu penting baginya","Cari keseimbangan: bagian mana yang butuh kualitas tinggi, bagian mana yang cukup cepat & sederhana","Sepakati keseimbangan itu bersama & jalankan"],answer:[0,1,2,3],explain:"Akui ini soal prioritas → pahami alasan tiap pihak → cari keseimbangan per bagian → sepakati. Bukan pembuktian menang-kalah.",hint:"Apa yang diakui sebelum mencari keseimbangan?"},
{n:86,type:"mcq",micro:"Kasus: perbedaan pendapat & tekanan waktu berulang",q:"Timmu selalu 'tidak sempat' membahas perbedaan pendapat karena tenggat, jadi selalu ikut suara terkeras. Solusi jangka panjang:",options:["Berhenti punya pendapat sendiri saat tenggat sudah dekat, karena perbedaan hanya memperlambat dan tim sebaiknya langsung mengikuti satu orang saja","Jadwalkan diskusi keputusan penting lebih awal (bukan di detik terakhir) & sepakati mekanisme keputusan cepat yang tetap mendengar semua (mis. tiap orang 1 menit, lalu voting)","Terima saja bahwa tim akan mengikuti suara yang paling keras, karena tak ada waktu mendengar setiap anggota saat tenggat mepet, dan itu dianggap wajar"],answer:1,explain:"Pola 'tidak sempat' sering karena keputusan dibahas terlalu telat. Membahas lebih awal + mekanisme cepat menjaga perbedaan tetap didengar.",hint:"Bahas lebih awal + mekanisme cepat yang mendengar semua, atau ikut yang terkeras?"},
{n:87,type:"tf",micro:"Menghargai perbedaan pendapat berlaku dua arah",q:"Benar atau Salah: Menghormati perbedaan pendapat berarti kamu berhak menyampaikan pandanganmu dengan sopan DAN kamu menghormati hak orang lain untuk berpandangan berbeda darimu.",answer:true,explain:"Ini timbal balik: kamu menyuarakan diri dengan hormat, & memberi ruang yang sama bagi orang lain — termasuk saat mereka tidak setuju denganmu.",hint:"Timbal balik, atau hanya hakmu?"},
{n:88,type:"mcq",micro:"Kasus: perbedaan pendapat memicu perpecahan tim",q:"Perbedaan pendapat yang tidak dikelola sudah membuat tim terbelah & saling dingin. Langkah pemulihan:",options:["Biarkan saja perselisihan itu sampai proyek selesai, lalu bubarkan tim begitu tugas dikumpulkan tanpa pernah membahas apa yang sebenarnya terjadi, walaupun hal itu membuat suasana dan kerja sama tim jadi makin sulit","Salah satu kelompok mendominasi dan mengabaikan kelompok yang lain, supaya keputusan cepat diambil dan keributan dalam tim tidak berlarut-larut, padahal cara itu hanya membuat masalahnya menumpuk dan makin besar nanti","Adakan pertemuan khusus: akui masalahnya terbuka, tetapkan aturan bicara hormat, dengar kedua sisi penuh, cari titik temu & keputusan lewat mekanisme adil, & tegaskan komitmen tetap satu tim"],answer:2,explain:"Perpecahan yang sudah terjadi butuh pertemuan yang sengaja untuk membicarakannya, bukan dibiarkan atau diselesaikan dengan dominasi.",hint:"Pertemuan khusus untuk membicarakan + mekanisme adil, atau biarkan / dominasi?"},
{n:89,type:"mcq",micro:"Kasus: kamu benar tapi tim memilih salah",q:"Tim, setelah mendengar kekhawatiranmu, tetap memilih rencana yang menurutmu keliru. Beberapa minggu kemudian, masalah yang kamu peringatkan benar-benar terjadi. Sikap yang matang:",options:["Bantu tim mengatasi masalah sekarang tanpa berkata 'kan aku sudah bilang'; setelah tenang, sarankan agar lain kali kekhawatiran yang spesifik ditimbang lebih serius","'Tuh kan, kalian sih tidak mau mendengarkan aku dari awal!' dikatakan berulang-ulang, supaya tim menyadari kesalahan mereka dan lebih menghargaimu","Menolak membantu karena 'itu akibat pilihan kalian sendiri', supaya mereka merasakan konsekuensi dari tidak mendengarkan kekhawatiranmu"],answer:0,explain:"Membuktikan 'aku benar' dengan menyalahkan hanya merusak tim. Membantu mengatasi + memberi masukan proses ke depan jauh lebih berharga.",hint:"Bantu atasi + masukan proses, atau 'kan aku bilang' / menolak bantu?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu akan memimpin tim OSIS 8 orang selama setahun. Kamu tahu tim ini punya beberapa anggota yang keras & suka mendominasi, dan beberapa yang sangat pendiam. Rancang bagaimana kamu membangun budaya tim di mana perbedaan pendapat dihargai — semua berani bersuara, diskusi tetap hormat, dan keputusan tetap bisa diambil. Minimal 6 praktik konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 praktik konkret dengan alasan: kesepakatan cara berdiskusi bersama, sengaja meminta pendapat yang pendiam lebih dulu, menulis pendapat sebelum diskusi lisan, menegakkan aturan diskusi konsisten untuk semua (termasuk yang keras & teman), mekanisme keputusan jelas + batas waktu, menghargai yang berbeda pendapat & yang berubah pikiran (tidak mengejek), menegaskan dukungan setelah keputusan + follow up yang kecewa, refleksi berkala.",hint:"Bangun budaya: kesepakatan diskusi, ruang untuk yang pendiam (tanya duluan/tulis dulu), penegakan konsisten, mekanisme keputusan + batas waktu, hargai perbedaan & perubahan pikiran, dukungan setelah keputusan, refleksi.",sample:"(1) Di awal, tim membuat kesepakatan bersama soal cara berdiskusi: bicara bergantian, kritik ide bukan orang, tidak menyindir/mengejek, semua pendapat didengar sebelum keputusan. Alasan: aturan yang disepakati bersama lebih dipatuhi & memberi rasa aman. (2) Dalam rapat, aku sengaja meminta pendapat anggota pendiam lebih dulu atau secara khusus ('menurutmu gimana, [nama]?') sebelum yang keras mengisi ruang. Alasan: setelah suara keras mendominasi, yang pendiam sulit bicara. (3) Untuk topik penting, aku minta tiap orang menulis pendapatnya dulu (di kertas/chat) sebelum diskyci lisan. Alasan: menulis dulu membuat yang lambat berpikir & yang pendiam tetap tersampaikan, tidak tenggelam. (4) Aku menegakkan aturan diskusi secara konsisten & sama untuk semua — kalau ada yang menyindir atau memotong, aku ingatkan dengan tenang, termasuk kepada anggota yang keras & teman dekatku. Alasan: penegakan pilih-pilih menghancurkan kepercayaan pada aturan. (5) Aku memakai mekanisme keputusan yang jelas (dengar semua → cari titik temu → kalau perlu voting), dengan batas waktu diskusi supaya menghargai perbedaan tidak jadi kebuntuan. Alasan: tim tetap harus bisa bergerak. (6) Aku menghargai secara terbuka orang yang menyampaikan pandangan berbeda dengan baik & orang yang berubah pikiran setelah mendengar argumen — tidak mengejek 'nah kan'. Alasan: kalau berbeda pendapat & mengaku keliru dihukum, orang akan menyembunyikannya. (7) Setelah keputusan, aku menegaskan 'kekhawatiran semua tercatat, keputusan diambil bareng, sekarang kita dukung' & follow up pribadi ke yang kecewa. (8) Berkala, tim merefleksikan: apakah semua merasa didengar? apa yang perlu diperbaiki soal cara kita berdiskusi?"},
{n:91,type:"mcq",micro:"Kasus: perbedaan pendapat di media sosial/publik",q:"Seorang anggota tim memposting pendapat pribadi (bukan atas nama tim) yang berbeda dari mayoritas tim. Sikap:",options:["Menyerang balik di media sosial dengan postingan yang membantah pendapatnya, supaya publik tahu bahwa mayoritas tim tidak sependapat dengannya","Itu haknya sebagai individu; selama tidak mengatasnamakan tim atau menyerang anggota lain, tim menghormati kebebasan berpendapat pribadinya","Menuntut dia menghapus postingan itu karena 'memalukan tim', & mengancam mengeluarkan dia dari tim bila ia menolak melakukannya segera"],answer:1,explain:"Menghormati perbedaan termasuk menghormati bahwa anggota tim adalah individu dengan pandangan sendiri di luar konteks tim.",hint:"Hormati kebebasan pribadinya (selama tidak atas nama tim / menyerang), atau tuntut hapus / serang balik?"},
{n:92,type:"tf",micro:"Refleksi: perbedaan pendapat bukan musuh kerja sama",q:"Benar atau Salah: Perbedaan pendapat bukanlah lawan dari kerja sama — justru kerja sama yang baik adalah kemampuan sekelompok orang dengan pandangan berbeda untuk tetap bekerja menuju tujuan bersama dengan saling menghormati.",answer:true,explain:"Kalau kerja sama berarti 'semua harus berpikir sama', ia rapuh & miskin ide. Kerja sama sejati merangkul perbedaan.",hint:"Perbedaan lawan kerja sama, atau bagian darinya?"},
{n:93,type:"mcq",micro:"Kasus: menghargai saat lelah & tertekan",q:"Kamu lelah & tertekan, & seorang anggota menyampaikan pendapat berbeda yang membuatmu ingin menyahut kasar. Sikap:",options:["Sahut kasar saja karena kamu capek, dan biarkan orang itu menerima nadamu apa adanya di depan teman-teman, sebab menahan diri melelahkan","Diam dan memusuhi dia sepanjang sisa hari, lalu membalasnya dengan sindiran halus ketika ada kesempatan lain, di hadapan anggota lain","Sadari kondisimu: 'Maaf, aku lagi capek. Boleh kita bahas ini nanti setelah aku bisa mikir lebih jernih?' — tunda daripada merespons kasar"],answer:2,explain:"Kondisimu memengaruhi caramu menanggapi. Menunda dengan jujur lebih baik daripada merusak diskusi & hubungan karena lelah.",hint:"Sadari kondisi + tunda, atau sahut kasar / memusuhi?"},
{n:94,type:"mcq",micro:"Kasus: perbedaan pendapat & keadilan bagi yang minoritas",q:"Dalam tim, satu anggota selalu jadi minoritas dalam setiap keputusan & mulai merasa suaranya tidak berarti. Sikap tim:",options:["Pastikan pendapatnya benar-benar didengar & ditimbang tiap kali (bukan sekadar formalitas); cari keputusan yang sesekali mengakomodasi pandangannya bila masuk akal; akui kontribusinya","Biarkan saja, dia memang sering kalah suara dan itulah risiko pengambilan keputusan bersama yang harus diterima oleh anggota tim tanpa perlu dibahas lagi atau diberi perhatian khusus oleh pemimpin","Suruh dia berhenti punya pendapat yang berbeda dari mayoritas supaya tidak terus merasa kalah dan keputusan tim lebih cepat, sehingga tim bisa fokus bekerja"],answer:0,explain:"Selalu kalah suara berbeda dari tidak didengar. Tim yang sehat memastikan minoritas benar-benar ditimbang & sesekali diakomodasi bila beralasan.",hint:"Pastikan benar-benar didengar & sesekali diakomodasi, atau biarkan / suruh diam?"},
{n:95,type:"tf",micro:"Menghargai perbedaan = mendengar, bukan menyerah",q:"Benar atau Salah: Menghormati pendapat yang berbeda pada dasarnya berarti mengalah & mengikuti pendapat itu, agar tidak ada yang tersinggung.",answer:false,explain:"Sebaliknya, menghargai berarti mendengarkan dengan serius & mempertimbangkan — bukan otomatis menyerah atau membiarkan yang paling keras selalu menang. Ini tentang proses yang adil, bukan siapa yang mengalah.",hint:"Mendengar & menimbang serius, atau otomatis menyerah / yang keras menang?"},
{n:96,type:"mcq",micro:"Kasus: refleksi soal cara kamu menghadapi perbedaan",q:"Cara melatih dirimu menghadapi perbedaan pendapat lebih baik:",options:["Mengabaikan evaluasi caramu menghadapi perbedaan setelah diskusi berakhir, karena yang penting keputusannya sudah diambil dan pekerjaan berlanjut, lalu pindah ke topik lain","Setelah diskusi: apakah aku benar-benar mendengar sisi lain? apakah aku menyerang ide atau orang? apakah aku terbuka berubah pikiran? apa satu hal yang akan kuperbaiki?","Menyimpulkan bahwa orang lain yang tidak bisa menghargai perbedaan, sehingga kamu sendiri tidak merasa perlu mengubah kebiasaanmu dalam berdiskusi"],answer:1,explain:"Meninjau caramu sendiri menghadapi perbedaan (bukan hanya menilai orang lain) mempercepat kamu jadi rekan diskusi yang lebih baik.",hint:"Evaluasi caramu sendiri, atau menyalahkan orang lain / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti menghargai perbedaan pendapat:",options:["Hindari perbedaan pendapat dengan diam dan setuju demi kedamaian, serta anggap setiap perbedaan sebagai ancaman bagi kekompakan tim yang harus dicegah, dan hal itu tidak perlu dibahas bersama anggota lain, agar tim tampak rukun","Menangkan setiap perbedaan pendapat dengan argumen sekuat mungkin, karena tim bekerja paling baik bila anggota akhirnya mengikuti pendapat yang paling kuat, dan anggota yang kalah cukup menerima, tanpa perlu dicatat","Anggap perbedaan pendapat wajar & berpotensi berguna; dengar sampai paham; kritik ide bukan orang; sampaikan pandanganmu dengan alasan & nada hormat; cari titik temu & putuskan bersama lewat mekanisme adil; dukung keputusan meski bukan pilihanmu; jaga hubungan"],answer:2,explain:"Ringkasan: wajar & berguna + dengar sampai paham + kritik ide bukan orang + alasan + nada hormat + titik temu + mekanisme adil + dukung hasil + jaga hubungan.",hint:"Wajar & berguna, dengar, kritik ide, alasan+hormat, titik temu, mekanisme adil, dukung hasil, jaga hubungan — rangkai."},
{n:98,type:"tf",micro:"Refleksi: menghargai perbedaan melayani hasil & hubungan",q:"Benar atau Salah: Menghargai perbedaan pendapat dengan baik menghasilkan dua hal: keputusan yang lebih matang & teruji, DAN hubungan tim yang tetap solid meski anggota sering berbeda pandangan.",answer:true,explain:"Kalau keputusan matang tapi tim jadi saling dingin, atau tim akur tapi keputusan berlubang karena tidak ada yang berani berbeda — keduanya belum berhasil.",hint:"Keputusan matang + hubungan solid, atau salah satu?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan menghargai perbedaan",q:"Cara termudah mulai jadi lebih baik dalam menghargai perbedaan pendapat minggu ini:",options:["Saat seseorang menyampaikan pendapat berbeda, latih satu hal: tahan reaksi awal, tanyakan 'apa yang bikin kamu berpikir begitu?', & dengarkan jawabannya penuh sebelum menanggapi","Menunggu sampai tim kita menjadi lebih dewasa & lebih dulu pandai menghargai perbedaan, baru kemudian kamu mulai mencoba kebiasaan itu bersama mereka nanti","Berhenti menyampaikan pendapat supaya tidak ada perbedaan dengan anggota lain, sehingga kamu tidak perlu belajar menanganinya lagi di tim"],answer:0,explain:"Kebiasaan menghargai perbedaan dimulai dari satu tindakan kecil: menahan reaksi & bertanya alasan sebelum membantah.",hint:"Latih tahan reaksi + tanya alasan, atau menunggu / berhenti berpendapat?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi menghargai perbedaan",q:"Tulis 'aturan pribadi tentang menghargai perbedaan pendapat' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: anggap perbedaan wajar & berguna, dengar sampai paham + pantulkan, kritik ide bukan orang + alasan + nada tenang, tahan reaksi & tanya alasan, terbuka berubah pikiran & tidak mengejek yang berubah, dukung keputusan adil meski bukan pilihan, jaga hubungan (soal ide bukan pribadi).",hint:"Ambil satu pelajaran tiap fase — perbedaan wajar & berguna, dengar+pantulkan, kritik ide+alasan+nada, tahan reaksi+tanya alasan, terbuka berubah, dukung keputusan adil, jaga hubungan — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Aku menganggap perbedaan pendapat sebagai hal wajar & kesempatan menemukan keputusan lebih baik, bukan tanda konflik — karena tim yang selalu setuju sering tidak memeriksa kesalahannya. (2) Sebelum membantah, aku mendengarkan pendapat orang sampai selesai & mengulang intinya untuk memastikan aku paham — karena banyak 'perbedaan' sebenarnya salah paham. (3) Aku mengkritik ide, bukan orangnya, dan menyampaikannya dengan alasan spesifik & nada tenang — karena serangan pribadi menutup telinga & merusak hubungan. (4) Aku menahan reaksi 'itu konyol' & menggantinya dengan pertanyaan 'apa yang bikin kamu berpikir begitu?' — karena reaksi cepat sering emosi & meleset. (5) Aku bersedia mengubah pendapatku bila ada argumen lebih baik, dan aku tidak mengejek orang yang berubah pikiran — karena keterbukaan adalah kekuatan, bukan kelemahan. (6) Setelah tim memutuskan lewat cara yang adil, aku mendukung keputusan itu meski bukan pilihanku, sambil boleh mencatat kekhawatiranku — karena menghormati proses berarti menerima hasilnya. (7) Aku menegaskan bahwa perbedaan pendapat soal ide tidak mengubah hubungan: 'kita beda pendapat, tapi tetap satu tim'."},
];
